{"command": "python3 -c "
import sys
import subprocess

# First try to download just subtitles with different formats
url = 'https://www.youtube.com/watch?v=1htKBjuUWec'

print('Trying to download subtitles in various formats...')

# Try to get subtitles in JSON format
try:
    result = subprocess.run(['yt-dlp', '--skip-download', '--write-auto-sub', '--sub-format', 'json3', '--sub-lang', 'en', '--output', 'transcript', url], 
                          capture_output=True, text=True, timeout=30)
    if result.returncode == 0:
        print('JSON subtitles download succeeded')
    else:
        print('JSON subtitles download failed')
except Exception as e:
    print(f'JSON attempt failed: {e}')

# Try VTT format
try:
    result = subprocess.run(['yt-dlp', '--skip-download', '--write-auto-sub', '--sub-format', 'vtt', '--sub-lang', 'en', '--output', 'transcript', url], 
                          capture_output=True, text=True, timeout=30)
    if result.returncode == 0:
        print('VTT subtitles download succeeded')
    else:
        print('VTT subtitles download failed')
except Exception as e:
    print(f'VTT attempt failed: {e}')

print('\\nChecking for downloaded subtitle files...')
import os
files = os.listdir('.')
for f in files:
    if 'transcript' in f.lower() or '.vtt' in f.lower() or '.json' in f.lower() or '.srt' in f.lower():
        print(f'Found: {f}')
""}

